// CSD_RATIONALE_BEGIN
// Strategy: GSM-Symbolic math word-problem solving with a single constrained
// final-answer span.  The model reasons freely in plain text for up to 75 % of
// the step budget (preamble), then GenerateWithPrefixAndManagedSpan forces
// entry into exactly ONE "<<expr>>" span and handles open/close bookkeeping
// and all Dafny proof obligations internally.  Task guidance steers the model
// toward a single well-formed arithmetic expression and explicitly forbids
// multi-step intermediate spans, LaTeX, and banned builtins.  When the step
// budget is zero the method is a no-op and satisfies all postconditions via
// the maxSteps == 0 disjunct.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: insideConstrainedOut := insideConstrained and
//   currentConstrainedOut := currentConstrained.  The method precondition
//   (insideConstrained ==> parser.IsValidPrefix(currentConstrained)) ensures
//   the invariant holds before any helper is called.
//
//   After GenerateWithPrefixAndManagedSpan: the helper's own postcondition
//   states insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut),
//   so the invariant is re-established on every return path from the helper.
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps  (steps == cost after the body)
//
//   Initialization: generated := generatedPrefix gives |generated| == |generatedPrefix|
//   and cost := 0, matching 0 steps consumed.
//
//   maxSteps == 0 branch: generated is unchanged, cost stays 0, so
//   |generated| <= |generatedPrefix| + 0 == |generatedPrefix| + maxSteps.
//
//   else branch: GenerateWithPrefixAndManagedSpan's postcondition guarantees
//   |generatedOut| <= |generatedPrefix| + maxSteps; setting cost := maxSteps
//   satisfies cost <= maxSteps and cost > 0 (maxSteps >= 1 in this branch),
//   which discharges the progress postcondition disjunct.
// CSD_PROOF_SKETCH_END

// ── Initialise all out-parameters ──────────────────────────────────────────
generated              := generatedPrefix;
insideConstrainedOut   := insideConstrained;
currentConstrainedOut  := currentConstrained;
cost                   := 0;

if maxSteps == 0 {
  // Zero budget: maxSteps == 0 disjunct in the last postcondition fires;
  // all other postconditions hold trivially from the initialisation above.
} else {
  // Append guidance once, before the first LM generation call.
  helpers.AppendTaskGuidance(lm,
    "Solve step by step in plain text. " +
    "At the very END, write the final answer as exactly ONE <<expr>>. " +
    "Combine ALL parts of the calculation into this ONE expression. " +
    "Example: <<int(n * frac_1 * frac_2)>> or <<total // n1 + (total * t) // n2>>. " +
    "Inside <<>>: variable names without braces (n not {n}, frac_1 not {frac_1}), " +
    "integers, +, -, *, /, //, %, (, ), int() ONLY. " +
    "Use // for integer division. " +
    "FORBIDDEN inside <<>>: max(), min(), abs(), floor(), ceil(), " +
    "{braces}, $, **, LaTeX, HTML tags, any other functions. " +
    "Do NOT write multiple <<>> blocks for intermediate steps " +
    "— ONE final <<expr>> only.");

  // Allow 75 % of the budget for unconstrained preamble reasoning.
  var prefixBudget: nat := (maxSteps * 75) / 100;
  // Guard: GenerateWithPrefixAndManagedSpan requires prefixBudget <= maxSteps.
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  // Full managed decode: free preamble → forced span open → constrained
  // expression → span close, all within maxSteps total token-steps.
  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt,
    generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget,
    validTokenGroups, 10.0, 8,
    eosToken
  );
  generated             := g;
  insideConstrainedOut  := ic;
  currentConstrainedOut := cc;

  // Account for the full budget consumed by the managed span helper.
  cost := maxSteps;
}
